<script setup>
defineProps({ result:Object })
function safeUrl(url) { try { const u=new URL(url); return ['https:','http:'].includes(u.protocol)?u.href:null } catch{return null} }
</script>
<template><section class="card"><span class="eyebrow">04 / TRACEABLE EVIDENCE</span><h2>证据与来源</h2><p v-if="!result?.citations?.length" class="empty">当前未获得通过引用校验的证据引用。</p><article class="source" v-for="s in result?.sources || []" :key="s.source_id"><a v-if="safeUrl(s.url)" :href="safeUrl(s.url)" target="_blank" rel="noopener noreferrer">{{ s.title }} ↗</a><strong v-else>{{ s.title }}</strong><p class="muted">{{ s.source_id }} · {{ s.publisher || s.institution || '机构未返回' }}</p><span v-for="c in s.citations || []" :key="c.evidence_id" class="tag">{{ c.evidence_id }} · {{ c.section || c.chunk_id || '图谱关系' }}</span></article><details v-if="result?.graphrag?.evidence?.length"><summary>查看实际检索证据与适用范围</summary><article class="source" v-for="e in result.graphrag.evidence" :key="e.evidence_id"><strong>{{ e.evidence_id }} · {{ e.content?.title || e.kind }}</strong><p>分级：{{ e.evidence_scope?.status || '未返回' }} · 地区：{{ e.content?.region?.length ? e.content.region : '未知' }}</p><p>{{ e.content?.text || '图谱证据，请查看完整返回。' }}</p><p class="muted">{{ e.scope_warnings?.join('；') }}</p></article></details></section></template>
